<?php defined('BASEPATH')or exit('No direct script access allowed');$company_page_title='Agenda de faturas';require APPPATH.'views/admin/companies/layout_head.php';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_invoice_recurring'.$q);$hidden=function($action,$r=null)use($esc,$company_invoice_schedule_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_invoice_schedule_csrf" value="'.$esc($company_invoice_schedule_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';if($r)echo '<input type="hidden" name="schedule_id" value="'.(int)$r['id'].'"><input type="hidden" name="revision" value="'.(int)$r['revision'].'">';};$states=['active'=>'Ativa','paused'=>'Pausada','paused_processing'=>'Pausada com ocorrência pendente','processing'=>'Etapa pendente','completed'=>'Ciclos concluídos','cancelled'=>'Cancelada']; ?>
<section class="company-settings-card"><h1>Agenda de faturas</h1><p>Intervalos mensais ou personalizados por dias, semanas, meses e anos. A primeira data é a primeira emissão programada; o vencimento mantém o intervalo em dias. Cada execução processa uma ocorrência vencida por série.</p><p>O agendamento não cria boleto, assinatura ou débito bancário. Notificação automática é uma escolha explícita do contato e transporte próprios; fila confirmada não comprova aceite SMTP ou entrega.</p><p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_recurring')); ?>">Abrir séries históricas mensais</a></p><?php if($error){?><p role="alert"><?= $esc($error); ?></p><?php } ?>
<?php if($detail){?><div id="invoice-schedule-detail"><h2>Série <?= (int)$detail['id']; ?></h2><p><?= $esc($states[$detail['state']]??$detail['state']); ?> · Próxima data <?= $esc($detail['next_date']); ?> · Emissões <?= (int)$detail['completed_cycles']; ?> / <?= $detail['config']['cycles']===0?'Sem limite':(int)$detail['config']['cycles']; ?></p><p><?= $esc($detail['context']['identity']['legal_name']); ?> · <?= $esc($detail['context']['recipient']['name']); ?> · <?= $esc($detail['context']['currency']['name']); ?></p><p>Entrega: <?= $detail['config']['send']?'Notificação própria opt-in; fila não é prova de entrega.':'Notificação manual após emissão.'; ?></p>
<?php if($can_manage&&(int)$detail['actor_id']===$actor&&in_array($detail['state'],['active','processing'],true)){?><?= form_open($url());$hidden('run',$detail); ?><button type="submit"><?= $detail['state']==='processing'?'Retomar mesma ocorrência':'Processar próxima ocorrência vencida'; ?></button><?= form_close(); ?><?php } ?>
<?php if($can_manage){foreach(in_array($detail['state'],['active','processing'],true)?['pause','cancel']:(in_array($detail['state'],['paused','paused_processing'],true)?['resume','cancel']:($detail['state']==='completed'?['cancel']:[]))as$action){?><?= form_open($url());$hidden($action,$detail); ?><button type="submit"><?= ['pause'=>'Pausar e bloquear mensagens pendentes','resume'=>'Retomar com origem original','cancel'=>'Cancelar próximas emissões e mensagens pendentes'][$action]; ?></button><?= form_close(); ?><?php }} ?>
<?php if($detail['last_error']!==''){?><p role="status">Origem ou autorização exige revisão. Restaure o acesso legítimo para retomar ou cancele a série e crie outra após revisar os dados. Faturas e filas anteriores permanecem registradas.</p><?php } ?><table class="table"><thead><tr><th>Data</th><th>Etapa</th><th>Fatura</th><th>Fila</th></tr></thead><tbody><?php foreach($detail['runs']as$run){?><tr><td><?= $esc($run['run_date']); ?></td><td><?= $esc($run['state']); ?></td><td><?php if($run['canonical_invoice_id']!==null){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.(int)$run['canonical_invoice_id'])); ?>">Abrir fatura</a><?php }else{?>Emissão ainda não confirmada no vínculo<?php } ?></td><td><?= $run['canonical_queue_id']===null?'Fila ainda não confirmada':('Fila registrada #'.(int)$run['canonical_queue_id'].($run['queue_id']===null?'; vínculo pendente':'').'; entrega não comprovada'); ?></td></tr><?php } ?></tbody></table></div><?php } ?>
<h2>Séries desta empresa</h2><table class="table"><thead><tr><th>Série</th><th>Próxima data</th><th>Estado</th></tr></thead><tbody><?php foreach($directory as$row){?><tr><td><a href="<?= $esc($url('?schedule='.(int)$row['id'])); ?>"><?= (int)$row['id']; ?></a></td><td><?= $esc($row['next_date']); ?></td><td><?= $esc($states[$row['state']]??$row['state']); ?></td></tr><?php } ?></tbody></table>
<?php if($can_manage){?><h2>Nova série com a origem atual</h2><?= form_open($url());$hidden('create');$recurring_form=true;require APPPATH.'views/admin/companies/sales_form_fields.php'; ?><label for="schedule-custom"><input type="checkbox" id="schedule-custom" name="custom" value="1">Intervalo personalizado (dias, semanas ou anos exigem esta escolha)</label><label for="schedule-unit">Unidade</label><select id="schedule-unit" name="unit"><option value="month">Meses</option><option value="day">Dias</option><option value="week">Semanas</option><option value="year">Anos</option></select><label for="schedule-interval">Intervalo</label><input id="schedule-interval" name="interval" type="number" min="1" max="1000" value="1" required><label for="schedule-cycles">Emissões (0 = sem limite)</label><input id="schedule-cycles" name="cycles" type="number" min="0" max="10000" value="12" required><label for="schedule-send"><input id="schedule-send" name="send" value="1" type="checkbox">Notificar automaticamente cada fatura pela origem própria</label><label for="schedule-contact">Contato próprio do cliente com acesso a faturas</label><select id="schedule-contact" name="contact_id"><option value="0">Selecione apenas se optar por notificação</option><?php foreach($contacts as$c){?><option value="<?= (int)$c['id']; ?>"><?= $esc($c['company'].' — '.$c['firstname'].' '.$c['lastname'].' ('.$c['email'].')'); ?></option><?php } ?></select><button type="submit">Agendar com as escolhas acima</button><?= form_close(); ?><?php } ?></section>
